            {
                const index_t rls = r * rowInd0.rows();     //local stride
                for (index_t i = 0; i != rowInd0.rows(); ++i)
                {
                    const index_t ii = rowMap.index(rowInd0(i,ra),v.data().patchId,r); //N_i
                    if ( rowMap.is_free_index(ii) )
